void adaptive_capacity_forced_rhs(adaptive_capacity_forced_internal* internal, double t, double * state, double * dstatedt, double * output) {
  double N = state[0];
  // delay block for N_lag_fitness
  double N_lag_fitness;
  {
    const double t_true = t;
    const double t = t_true - internal->tau1;
    double N;
    if (t <= internal->initial_t) {
      N = internal->initial_N;
    } else {
      lagvalue(t, internal->adaptive_capacity_forced_use_dde, internal->delay_index_N_lag_fitness, 1, internal->delay_state_N_lag_fitness);
      N = internal->delay_state_N_lag_fitness[0];
    }
    N_lag_fitness = N;
  }
  // delay block for N_lag_resources
  double N_lag_resources;
  {
    const double t_true = t;
    const double t = t_true - internal->tau2;
    double N;
    if (t <= internal->initial_t) {
      N = internal->initial_N;
    } else {
      lagvalue(t, internal->adaptive_capacity_forced_use_dde, internal->delay_index_N_lag_resources, 1, internal->delay_state_N_lag_resources);
      N = internal->delay_state_N_lag_resources[0];
    }
    N_lag_resources = N;
  }
  double cap = internal->b1 * N_lag_resources;
  double cap2 = internal->b2 * N_lag_resources;
  double C = 0.0;
  cinterpolate_eval(t, internal->interpolate_C, &C);
  double Kt1 = C + internal->a1 + cap;
  double Kt2 = C + internal->a2 + cap2;
  double fit1 = internal->r - (internal->S / (double) Kt1) * N_lag_fitness;
  double K = (fit1 < internal->fmin ? Kt2 : Kt1);
  dstatedt[0] = internal->r * N - (internal->S * pow(N, internal->alpha)) / (double) K;
  if (output) {
    output[0] = internal->r - (internal->S * N / (double) K);
  }
}
void adaptive_capacity_forced_rhs_dde(size_t neq, double t, double * state, double * dstatedt, void * internal) {
  adaptive_capacity_forced_rhs((adaptive_capacity_forced_internal*)internal, t, state, dstatedt, NULL);
}
