void brander_taylor_rhs(brander_taylor_internal* internal, double t, double * state, double * dstatedt, double * output) {
  double S = state[1];
  double L = state[0];
  dstatedt[0] = L * (internal->phi * internal->alpha * internal->beta * S - internal->sigma);
  dstatedt[1] = internal->r * S * (1 - S / (double) internal->K) - internal->alpha * internal->beta * L * S;
}
