void food_limited_rhs(food_limited_internal* internal, size_t step, double * state, double * state_next, double * output) {
  double * pop = state + 3;
  double food_stored = state[0];
  double yield_actual = internal->yield_base * ((int) (step) >= internal->dim_yield_var ? internal->yield_var[internal->dim_yield_var - 1] : internal->yield_var[step + 1 - 1]);
  for (int i = 1; i <= internal->dim_cal_need; ++i) {
    internal->cal_need[i - 1] = pop[i - 1] * internal->cal_max * internal->food_need[i - 1];
  }
  for (int i = 1; i <= internal->dim_workers; ++i) {
    internal->workers[i - 1] = pop[i - 1] * internal->work_capacity[i - 1];
  }
  double total_cal_need = odin_sum1(internal->cal_need, 0, internal->dim_cal_need) * internal->dt;
  double total_workers = odin_sum1(internal->workers, 0, internal->dim_workers);
  double land_used = 1 - exp(-(internal->land_per_hour) * internal->work_hours * total_workers / (double) internal->land_max);
  double food_prod = yield_actual * internal->land_max * land_used * (1 - internal->set_aside) * internal->dt;
  double food_ratio = (food_prod) / (double) total_cal_need;
  state_next[0] = food_stored + food_prod - total_cal_need - internal->alpha * food_stored * internal->dt;
  for (int i = 1; i <= internal->dim_fert_actual; ++i) {
    internal->fert_actual[i - 1] = internal->fert_base[i - 1] * pgamma_cpp(food_ratio, 4.579627264, 0.10000000000000001);
  }
  for (int i = 1; i <= internal->dim_mort_rate; ++i) {
    internal->mort_rate[i - 1] = 1 - (internal->surv_base[i - 1] * pgamma_cpp(food_ratio, internal->surv_shape[i - 1], 0.10000000000000001));
  }
  state_next[2] = food_ratio;
  for (int i = 1; i <= internal->dim_births_by_age; ++i) {
    internal->births_by_age[i - 1] = Rf_rbinom(round(pop[i - 1]), 1 - pow((1 - internal->fert_actual[i - 1]), internal->dt));
  }
  for (int i = 1; i <= internal->dim_deaths; ++i) {
    internal->deaths[i - 1] = Rf_rbinom(round(pop[i - 1]), 1 - pow((1 - internal->mort_rate[i - 1]), internal->dt));
  }
  for (int i = 1; i <= internal->dim_pop_surviving; ++i) {
    internal->pop_surviving[i - 1] = pop[i - 1] - internal->deaths[i - 1];
  }
  double total_births = odin_sum1(internal->births_by_age, 0, internal->dim_births_by_age);
  for (int i = 1; i <= internal->dim_aging_up; ++i) {
    internal->aging_up[i - 1] = Rf_rbinom(round(internal->pop_surviving[i - 1]), internal->dt);
  }
  state_next[1] = total_births - odin_sum1(internal->deaths, 0, internal->dim_deaths);
  {
     int i = 1;
     state_next[3 + i - 1] = internal->pop_surviving[0] - internal->aging_up[0] + total_births;
  }
  for (int i = 2; i <= (internal->n_age - 1); ++i) {
    state_next[3 + i - 1] = (internal->pop_surviving[i - 1] - internal->aging_up[i - 1]) + internal->aging_up[i - 1 - 1];
  }
  {
     int i = internal->n_age;
     state_next[3 + i - 1] = internal->pop_surviving[internal->n_age - 1] + internal->aging_up[internal->n_age - 1 - 1];
  }
}
