void janssen_stochastic_rhs(janssen_stochastic_internal* internal, size_t step, double * state, double * state_next, double * output) {
  double P = state[0];
  double R = state[1];
  double epsilon = Rf_rnorm(0, internal->epsilon_sdev);
  double Q = internal->a * R * pow(P, internal->alpha);
  double R_next = R + internal->g * R * pow((R / (double) internal->c), internal->gamma) * (1 - R / (double) internal->c) - internal->eta * P;
  double h = internal->tau * (1 + epsilon) * Q;
  state_next[1] = (R_next < 0 ? 0 : R_next);
  double p_b = internal->rb * h / (double) 100;
  double p_d = internal->rd * (2 - h / (double) 100);
  double births = Rf_rbinom(round(P), p_b);
  double deaths = Rf_rbinom(round(P), p_d);
  state_next[0] = P + births - deaths;
}
