void nefedov_forced_rhs(nefedov_forced_internal* internal, double t, double * state, double * dstatedt, double * output) {
  double N = state[0];
  double K = state[1];
  dstatedt[0] = internal->r * N * (1 - N / (double) K);
  double food = 0.0;
  cinterpolate_eval(t, internal->interpolate_food, &food);
  double harvest = internal->q * food / (double) (internal->q - 1) * N / (double) (N + food / (double) (internal->q - 1));
  dstatedt[1] = harvest - N;
}
